import threading

from counter import Counter


def test_concurrent_increments():
    c = Counter()
    n_threads = 8
    per_thread = 2000

    def worker():
        for _ in range(per_thread):
            c.increment()

    threads = [threading.Thread(target=worker) for _ in range(n_threads)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert c.value == n_threads * per_thread

